namespace HdrPilot {
// RenoDX NR is a renderer, separate from the game's RenoDX HDR add-on.
public static class RenoNr {
 public const string Name="renodx-dlss5.addon64",Marker="hdlss-renodx-nr.json";
 public static string T(params string[] values){int i=Array.IndexOf(new[]{"it","en","es","fr","de","pt"},Core.Pref.Language);return values[i<0?1:i];}
 public static string RevisionHelp {get{return T("OptiScaler · Standard installa l’ultima release stabile del progetto ufficiale, controllata online al momento del download. Non installa un modello NR e mantiene Neural Rendering spento. Scegli Standard e premi Installa OptiScaler; configura poi l’upscaling nel menu del gioco e in OptiScaler. I modelli già presenti vengono conservati. Per attivare NR scegli invece un fork dedicato e installalo. Un add-on ReShade NR resta indipendente: Standard non lo spegne.\n\nLa scheda DLSS 5 · ReShade segue OptiScaler. Riconosce anche renodx-dlss5-v8.5-model.addon64 installato manualmente e ReShade installato da DLSS 5 · ReShade. Giallo indica file riconosciuti, non attivazione in gioco né ultima versione. Aggiornare un add-on manuale conserva il suo nome e crea un backup.","OptiScaler · Standard installs the latest stable release of the official project, checked online when downloading. It does not install an NR model and keeps Neural Rendering off. Select Standard and click Install OptiScaler; configure upscaling in the game and OptiScaler menus. Existing models are preserved. To enable NR, select and install a dedicated fork. A ReShade NR add-on remains independent: Standard does not disable it.\n\nThe DLSS 5 · ReShade tab follows OptiScaler. It recognizes manually installed renodx-dlss5-v8.5-model.addon64 and ReShade installed through DLSS 5 · ReShade. Yellow means recognized files, not activation in game or latest version. Updating a manual add-on preserves its filename and creates a backup.","OptiScaler · Standard instala la última versión estable oficial, comprobada al descargar. No instala modelos NR y mantiene Neural Rendering desactivado. Selecciona Standard e Instalar OptiScaler; configura el escalado en el juego y OptiScaler. Conserva modelos existentes. Para NR instala un fork dedicado. Standard no desactiva un complemento NR de ReShade.\n\nDLSS 5 · ReShade aparece después de OptiScaler. Reconoce renodx-dlss5-v8.5-model.addon64 manual y ReShade instalado desde DLSS 5 · ReShade. Amarillo indica archivos reconocidos, no activación ni última versión. Actualizar un complemento manual conserva su nombre y crea una copia de seguridad.","OptiScaler · Standard installe la dernière version stable officielle, vérifiée au téléchargement. Aucun modèle NR installé et Neural Rendering reste désactivé. Sélectionnez Standard puis Installer OptiScaler ; réglez la mise à l’échelle dans le jeu et OptiScaler. Les modèles existants sont conservés. Pour NR, installez un fork dédié. Standard ne désactive pas une extension NR ReShade.\n\nDLSS 5 · ReShade suit OptiScaler. Détecte renodx-dlss5-v8.5-model.addon64 manuel et ReShade installé via DLSS 5 · ReShade. Jaune indique des fichiers reconnus, pas leur activation ni la dernière version. La mise à jour manuelle conserve le nom et crée une sauvegarde.","OptiScaler · Standard installiert die neueste stabile offizielle Version, beim Download online geprüft. Kein NR-Modell wird installiert; Neural Rendering bleibt aus. Standard wählen und OptiScaler installieren; Upscaling im Spiel und OptiScaler einstellen. Vorhandene Modelle bleiben erhalten. Für NR einen passenden Fork installieren. Standard deaktiviert kein ReShade-NR-Add-on.\n\nDLSS 5 · ReShade folgt auf OptiScaler. Erkennt manuelles renodx-dlss5-v8.5-model.addon64 und ReShade aus DLSS 5 · ReShade. Gelb bedeutet erkannte Dateien, nicht Aktivierung oder neueste Version. Updates manueller Add-ons behalten den Namen und erstellen ein Backup.","OptiScaler · Standard instala a última versão estável oficial, verificada online ao descarregar. Não instala modelos NR e mantém Neural Rendering desligado. Escolha Standard e Instalar OptiScaler; configure upscaling no jogo e OptiScaler. Preserva modelos existentes. Para NR instale um fork dedicado. Standard não desativa complementos NR do ReShade.\n\nDLSS 5 · ReShade vem depois de OptiScaler. Reconhece renodx-dlss5-v8.5-model.addon64 manual e ReShade instalado em DLSS 5 · ReShades. Amarelo indica ficheiros reconhecidos, não ativação nem última versão. Atualizar um complemento manual preserva o nome e cria backup.");}}
 public static string EffectsHelp {get{return T("In DLSS 5 · ReShade trovi Lilium e Sharpening · AMD FidelityFX CAS. Lilium offre analisi e strumenti HDR: installare gli shader non attiva HDR da solo. CAS aumenta la nitidezza, con variante Lilium per SDR/HDR. Premi Installa selezionato, poi attiva l’effetto nel pannello ReShade in gioco. Parti da intensità bassa e confronta bordi e dettagli: troppo sharpening crea aloni. Se CAS è già incluso in Lilium, l’app evita una copia aggiuntiva; attivalo dal menu ReShade. Rimuovi selezionato rimuove il pacchetto gestito, non solo il singolo effetto. I vecchi pacchetti restano nei giochi e possono essere rimossi dalla gestione componenti.","DLSS 5 · ReShade offers Lilium and Sharpening · AMD FidelityFX CAS. Lilium provides HDR analysis and tools; installing shaders alone does not enable HDR. CAS sharpens the image with Lilium’s SDR/HDR variant. Click Install selected, then enable the effect in ReShade in game. Start low and compare edges and detail: excessive sharpening causes halos. If CAS is already included in Lilium, no extra copy is installed; enable it in ReShade. Remove selected removes the managed package, not just one effect. Older packages remain installed and can be removed through component management.","DLSS 5 · ReShade ofrece Lilium y Sharpening · AMD FidelityFX CAS. Lilium analiza HDR; instalar shaders no activa HDR. CAS mejora la nitidez en SDR/HDR. Instala el paquete y activa el efecto en ReShade. Empieza con intensidad baja para evitar halos. Si Lilium ya incluye CAS, no se instala otra copia. Eliminar seleccionado quita el paquete gestionado completo. Los paquetes antiguos se conservan y se pueden quitar desde la gestión de componentes.","DLSS 5 · ReShade propose Lilium et Sharpening · AMD FidelityFX CAS. Lilium analyse HDR ; installer les shaders n’active pas HDR. CAS améliore la netteté SDR/HDR. Installez le paquet puis activez l’effet dans ReShade. Commencez avec une faible intensité pour éviter les halos. Si Lilium contient déjà CAS, aucune copie supplémentaire. Retirer la sélection retire le paquet géré entier. Les anciens paquets sont conservés et restent supprimables via la gestion des composants.","DLSS 5 · ReShade bietet Lilium und Sharpening · AMD FidelityFX CAS. Lilium bietet HDR-Analyse; Shader-Installation allein aktiviert kein HDR. CAS schärft SDR/HDR. Paket installieren und Effekt in ReShade aktivieren. Mit geringer Stärke beginnen, um Halos zu vermeiden. Enthält Lilium bereits CAS, wird keine zusätzliche Kopie installiert. Auswahl entfernen entfernt das ganze verwaltete Paket. Alte Pakete bleiben erhalten und können in der Komponentenverwaltung entfernt werden.","DLSS 5 · ReShades oferece Lilium e Sharpening · AMD FidelityFX CAS. Lilium analisa HDR; instalar shaders não ativa HDR. CAS melhora nitidez SDR/HDR. Instale o pacote e ative o efeito no ReShade. Comece com intensidade baixa para evitar halos. Se Lilium já inclui CAS, não instala outra cópia. Remover selecionado remove o pacote gerido completo. Pacotes antigos são preservados e podem ser removidos na gestão de componentes.");}}
 public static string RevisionLog {get{return T("9 ottobre 2026 · Revisione locale: OptiScaler Standard senza NR, ultima stabile ufficiale; ReShade subito dopo OptiScaler, rilevamento add-on manuali e pulsanti installati gialli; Lilium e CAS, controllo duplicati; spaziatura HDR rivista. Guida e traduzioni aggiornate.","9 October 2026 · Local revision: official latest stable OptiScaler Standard without NR; ReShade after OptiScaler, manual add-on detection and yellow installed buttons; Lilium and CAS with duplicate checks; revised HDR spacing. Guide and translations updated.","9 octubre 2026 · Revisión local: OptiScaler Standard oficial estable sin NR; ReShade después de OptiScaler, detección manual y botones amarillos; Lilium y CAS sin duplicados; espaciado HDR revisado. Guía y traducciones actualizadas.","9 octobre 2026 · Révision locale : OptiScaler Standard officiel stable sans NR ; ReShade après OptiScaler, détection manuelle et boutons jaunes ; Lilium et CAS sans doublons ; espacement HDR corrigé. Guide et traductions actualisés.","9. Oktober 2026 · Lokale Revision: neuestes stabiles offizielles OptiScaler Standard ohne NR; ReShade nach OptiScaler, manuelle Erkennung und gelbe Schaltflächen; Lilium und CAS mit Duplikatprüfung; HDR-Abstände überarbeitet. Hilfe und Übersetzungen aktualisiert.","9 outubro 2026 · Revisão local: OptiScaler Standard oficial estável sem NR; ReShade após OptiScaler, deteção manual e botões amarelos; Lilium e CAS sem duplicados; espaçamento HDR revisto. Guia e traduções atualizados.");}}
 public static string FixLog {get{return T("9 ottobre · Corretta la descrizione ReShade NR: rimossi riferimenti al video. Il profilo API non confermato mostra ora una spiegazione e il comando Eseguibile e grafica è disponibile nella scheda.","9 October · ReShade NR description corrected: video references removed. An unconfirmed API profile now shows an explanation; Executable and graphics is available in the tab.","9 octubre · Descripción ReShade NR corregida, sin referencias al vídeo. API no confirmada con explicación y acceso a Ejecutable y gráficos en la pestaña.","9 octobre · Description ReShade NR corrigée, sans références à la vidéo. API non confirmée expliquée et accès à Exécutable et graphismes dans l’onglet.","9. Oktober · ReShade-NR-Beschreibung ohne Videobezüge. Nicht bestätigte API wird erklärt; Programmdatei und Grafik im Tab verfügbar.","9 outubro · Descrição ReShade NR corrigida, sem referências ao vídeo. API não confirmada explicada e acesso a Executável e gráficos na aba.");}}
 public static string Title {get{return "DLSS 5 · ReShade";}}
 public static string ModelHelp {get{return T("9 ottobre 2026 · Corretto il cambio del modello NR con add-on ReShade presenti. In DLL e Streamline → Neural Rendering scegli la variante per la tua GPU e premi Installa versione selezionata, a gioco chiuso. Cambia solo nvngx_dlssnr.dll con backup: non aggiunge un secondo iniettore e conserva gli add-on. Puoi ripristinare il modello precedente; per rimuovere il modello senza sostituirlo devi prima rimuovere l’add-on NR. Rimane il blocco contro due iniettori NR.","9 October 2026 · Fixed NR model changes with ReShade add-ons present. In DLLs and Streamline → Neural Rendering choose your GPU variant and click Install selected version with the game closed. Only nvngx_dlssnr.dll changes, with backup; add-ons are preserved and no second injector is installed. A previous model can be restored; removing the model without replacement requires removing the NR add-on first. Dual NR injector protection remains.","9 de octubre de 2026 · Corregido el cambio del modelo NR con complementos ReShade. En DLL y Streamline → Neural Rendering elige la variante de tu GPU y pulsa Instalar versión seleccionada con el juego cerrado. Solo cambia nvngx_dlssnr.dll con copia de seguridad; se conservan los complementos. Puedes restaurar el modelo anterior. Para eliminar el modelo sin sustituirlo, quita primero el complemento NR. Se mantiene la protección contra dos inyectores NR.","9 octobre 2026 · Changement du modèle NR corrigé avec des extensions ReShade. Dans DLL et Streamline → Neural Rendering, choisissez la variante GPU puis Installer la version sélectionnée, jeu fermé. Seul nvngx_dlssnr.dll change, avec sauvegarde ; les extensions restent intactes. Le modèle précédent peut être restauré. Pour supprimer le modèle sans remplacement, retirez d’abord l’extension NR. La protection contre deux injecteurs NR reste active.","9. Oktober 2026 · NR-Modellwechsel mit vorhandenen ReShade-Add-ons korrigiert. Unter DLLs und Streamline → Neural Rendering die GPU-Variante wählen und Ausgewählte Version installieren anklicken, während das Spiel geschlossen ist. Nur nvngx_dlssnr.dll wird mit Sicherung ersetzt. Add-ons bleiben erhalten. Das vorherige Modell kann wiederhergestellt werden. Vor dem ersatzlosen Entfernen zuerst das NR-Add-on entfernen. Der Schutz gegen zwei NR-Injektoren bleibt bestehen.","9 de outubro de 2026 · Corrigida a troca do modelo NR com complementos ReShade. Em DLL e Streamline → Neural Rendering escolha a variante da GPU e Instalar versão selecionada, com o jogo fechado. Só nvngx_dlssnr.dll é alterado, com cópia de segurança; os complementos são preservados. Pode restaurar o modelo anterior. Para remover o modelo sem substituição, remova primeiro o complemento NR. A proteção contra dois injetores NR permanece.");}}
 public const string CurrentHash="ee99295d60426c9e05165ac4cb44a9ce773ff05b39bd7ae4a3c0f61e53b6c8a0";
 public const string SourcePage="https://discord.com/channels/1408098019194310818/1545049227321810974";
 public static string Intro {get{return T("RenoDX Neural Rendering tramite ReShade. Richiede DirectX 12, ReShade con supporto add-on e un modello NR compatibile. Installa i componenti, poi attiva Neural Rendering nel menu ReShade del gioco.","RenoDX Neural Rendering through ReShade. Requires DirectX 12, ReShade with add-on support and a compatible NR model. Install the components, then enable Neural Rendering in the in-game ReShade menu.","RenoDX Neural Rendering mediante ReShade. Requiere DirectX 12, ReShade con complementos y un modelo NR compatible. Instala los componentes y activa Neural Rendering en ReShade dentro del juego.","RenoDX Neural Rendering via ReShade. Nécessite DirectX 12, ReShade avec extensions et un modèle NR compatible. Installez les composants, puis activez Neural Rendering dans ReShade en jeu.","RenoDX Neural Rendering über ReShade. Benötigt DirectX 12, ReShade mit Add-ons und ein kompatibles NR-Modell. Komponenten installieren und Neural Rendering im ReShade-Spielmenü aktivieren.","RenoDX Neural Rendering via ReShade. Requer DirectX 12, ReShade com complementos e um modelo NR compatível. Instale os componentes e ative Neural Rendering no ReShade do jogo.");}}
 public static string Bundled(){string dir=Path.Combine(Core.Data,"renodx-nr-packages",CurrentHash);Directory.CreateDirectory(dir);string file=Path.Combine(dir,Name);using(var input=typeof(RenoNr).Assembly.GetManifestResourceStream("RenoNr-v8.5.addon64"))using(var output=File.Create(file)){if(input==null)throw Invalid();input.CopyTo(output);}if(DlssCore.Hash(file)!=CurrentHash)throw Invalid();ValidateAddon(file);return file;}
 public static string Policy {get{return T("Versione inclusa: v8.5-model, pubblicata su Discord il 4 ottobre. Prima di installare controlliamo il mirror per versioni superiori a 8.5; la rc10 non sostituisce questa build. Le nuove pubblicazioni Discord si verificano dal pulsante Apri download RenoDX e si importano. L’app non legge il tuo account Discord.","Included: v8.5-model, posted on Discord on 4 October. Before installing we check the mirror for versions above 8.5; rc10 does not replace this build. Check new Discord posts using Open RenoDX downloads and import them. The app does not access your Discord account.","Incluida: v8.5-model, publicada en Discord el 4 de octubre. Antes de instalar se buscan versiones superiores a 8.5 en el espejo; rc10 no sustituye esta versión. Abre las descargas RenoDX para comprobar e importar nuevas versiones de Discord. La app no accede a tu cuenta.","Version incluse : v8.5-model, publiée sur Discord le 4 octobre. Avant l’installation, recherche sur le miroir des versions supérieures à 8.5 ; rc10 ne remplace pas cette version. Ouvrez les téléchargements RenoDX pour vérifier et importer les nouveautés Discord. L’application n’accède pas à votre compte.","Enthalten: v8.5-model, am 4. Oktober auf Discord veröffentlicht. Vor der Installation wird der Mirror auf Versionen über 8.5 geprüft; rc10 ersetzt diesen Build nicht. Neue Discord-Versionen über RenoDX-Downloads öffnen prüfen und importieren. Die App greift nicht auf Ihr Konto zu.","Incluída: v8.5-model, publicada no Discord a 4 de outubro. Antes de instalar procuramos versões superiores a 8.5 no espelho; rc10 não substitui esta versão. Abra os downloads RenoDX para verificar e importar novidades do Discord. A aplicação não acede à sua conta.");}}
 public static string ChangeLog {get{return T("Prova locale · 8 ottobre 2026. Aggiunta la scheda DLSS 5 · ReShade per RenoDX NR: v8.5-model dal canale RenoDX, verifica SHA256 e controllo delle release successive del mirror, importazione separata v8.5-model del video, controllo dei conflitti NR e ripristino con backup. Guida e testi in sei lingue. Non ancora pubblicata.","Local preview · 8 October 2026. Added DLSS 5 · ReShade for RenoDX NR: v8.5-model from RenoDX, SHA256 verification and newer mirror release checks, separate import of the video's v8.5-model, NR conflict checks and restoration with backups. Guide and text in six languages. Not published yet.","Prueba local · 8 de octubre de 2026. Nueva pestaña DLSS 5 · ReShade: v8.5-model de RenoDX con SHA256 y búsqueda de versiones posteriores, importación separada de v8.5-model, control de conflictos NR y restauración con copias. Guía y textos en seis idiomas. Sin publicar.","Aperçu local · 8 octobre 2026. Nouvel onglet DLSS 5 · ReShade : v8.5-model RenoDX vérifiée par SHA256 et recherche des versions suivantes, import séparé de v8.5-model, contrôle des conflits NR et restauration avec sauvegardes. Guide en six langues. Non publié.","Lokale Vorschau · 8. Oktober 2026. Neues Register DLSS 5 · ReShade: SHA256-geprüftes RenoDX v8.5-model und Prüfung auf neuere Versionen, separater Import von v8.5-model, NR-Konfliktprüfung und Wiederherstellung mit Sicherungen. Anleitung in sechs Sprachen. Noch nicht veröffentlicht.","Prévia local · 8 de outubro de 2026. Nova aba DLSS 5 · ReShade: v8.5-model RenoDX com SHA256 e procura de versões posteriores, importação separada de v8.5-model, verificação de conflitos NR e restauro com cópias. Guia em seis idiomas. Ainda não publicada.");}}
 public static string Help {get{string text=T(
 "Percorso RenoDX Neural Rendering, distinto da RenoDX HDR e dal precedente AIO. Il video usa renodx-dlss5-v8.5-model.addon64 da Discord; il download qui disponibile è la diversa 8.5.0-rc10 dal mirror community RankFTW/rhi-repo. Per il file esatto del video usa Importa add-on.\n\n1. Scegli l’eseguibile x64 e DirectX 12 in Eseguibile e grafica. Questa integrazione non installa bridge DX11/Vulkan.\n2. Se usi OptiScaler, disabilita Neural Rendering e applica le impostazioni prima di installare questo add-on. OptiScaler può rimanere per altre funzioni.\n3. Premi Installa ReShade con add-on, poi Installa / aggiorna RenoDX NR oppure Importa add-on. Il modello NR esistente viene conservato; se manca viene scaricato per RTX 4000/5000. Ogni modifica ha un backup.\n4. Riavvia il gioco, attiva DLSS SR e apri ReShade con Home (o il tasto configurato). Nel pannello DLSS 5 Neural Rendering verifica che il modello sia caricato e abilita NR. Parti da un passaggio; confronta FPS e immagine nella stessa scena. Render lavora prima dell’upscaling, Upscaled dopo; Present può costare molto. Le opzioni dipendono dalla build.\n\nIl Neural Rendering può ridurre gli FPS: nessuna garanzia di fluidità, HDR o compatibilità universale. FG/MFG e Streamline restano funzioni separate. L’installazione non disattiva anti-cheat. Rimuovi RenoDX NR elimina solo l’add-on riconosciuto con copia di recupero. Conserva ReShade, il modello NR e gli altri add-on.",
 "RenoDX Neural Rendering is separate from RenoDX HDR and the previous AIO. The video uses renodx-dlss5-v8.5-model.addon64 from Discord; this download is the different 8.5.0-rc10 from community mirror RankFTW/rhi-repo. Use Import add-on for the exact video file.\n\n1. Select the x64 executable and DirectX 12 in Executable and graphics. This integration does not install DX11/Vulkan bridges.\n2. If using OptiScaler, disable Neural Rendering and apply settings before installing this add-on. OptiScaler may remain for other features.\n3. Click Install ReShade with add-ons, then Install / update RenoDX NR or Import add-on. An existing NR model is preserved; a missing model is downloaded for RTX 4000/5000. Changes are backed up.\n4. Restart the game, enable DLSS SR and open ReShade with Home (or your configured key). In DLSS 5 Neural Rendering, verify model loading and enable NR. Start with one pass; compare FPS and image in the same scene. Render runs before upscaling, Upscaled after; Present can be expensive. Options depend on the build.\n\nNeural Rendering can reduce FPS: smoothness, HDR and universal compatibility are not guaranteed. FG/MFG and Streamline remain separate. Installation does not disable anti-cheat. Remove RenoDX NR deletes only the recognized add-on with a recovery copy. ReShade, the NR model and other add-ons are preserved.",
 "RenoDX Neural Rendering es independiente de RenoDX HDR y del AIO anterior. El vídeo usa renodx-dlss5-v8.5-model.addon64 de Discord; la descarga disponible es la distinta 8.5.0-rc10 del espejo comunitario RankFTW/rhi-repo. Usa Importar complemento para el archivo exacto.\n\n1. Selecciona el ejecutable x64 y DirectX 12 en Ejecutable y gráficos. No se instalan puentes DX11/Vulkan.\n2. Si usas OptiScaler, desactiva Neural Rendering y aplica los ajustes antes de instalar. OptiScaler puede conservar sus otras funciones.\n3. Pulsa Instalar ReShade con complementos y después Instalar / actualizar RenoDX NR o Importar complemento. Se conserva el modelo NR existente; si falta, se descarga para RTX 4000/5000. Se crean copias de seguridad.\n4. Reinicia el juego, activa DLSS SR y abre ReShade con Inicio o tu tecla configurada. En DLSS 5 Neural Rendering comprueba el modelo y activa NR. Empieza con una pasada y compara FPS e imagen en la misma escena. Render actúa antes del escalado, Upscaled después; Present puede ser costoso. Las opciones dependen de la versión.\n\nNeural Rendering puede reducir los FPS: fluidez, HDR y compatibilidad no están garantizados. FG/MFG y Streamline son independientes. No se desactiva el antitrampas. Quitar RenoDX NR elimina solo el complemento reconocido con copia de recuperación. Conserva ReShade, el modelo NR y otros complementos.",
 "RenoDX Neural Rendering est distinct de RenoDX HDR et de l’ancien AIO. La vidéo utilise renodx-dlss5-v8.5-model.addon64 depuis Discord ; le téléchargement proposé est la version différente 8.5.0-rc10 du miroir communautaire RankFTW/rhi-repo. Utilisez Importer l’extension pour le fichier exact.\n\n1. Choisissez l’exécutable x64 et DirectX 12 dans Exécutable et graphismes. Aucun pont DX11/Vulkan n’est installé.\n2. Avec OptiScaler, désactivez Neural Rendering et appliquez avant l’installation. Ses autres fonctions peuvent rester.\n3. Cliquez sur Installer ReShade avec extensions, puis Installer / mettre à jour RenoDX NR ou Importer l’extension. Le modèle NR existant est conservé ; sinon un modèle RTX 4000/5000 est téléchargé. Les modifications sont sauvegardées.\n4. Relancez le jeu, activez DLSS SR et ouvrez ReShade avec Début ou votre raccourci. Dans DLSS 5 Neural Rendering, vérifiez le modèle et activez NR. Commencez par une passe et comparez FPS et image dans la même scène. Render agit avant l’agrandissement, Upscaled après ; Present peut être coûteux. Les options dépendent de la version.\n\nNeural Rendering peut réduire les FPS : fluidité, HDR et compatibilité ne sont pas garantis. FG/MFG et Streamline restent séparés. L’anti-triche n’est pas désactivé. Retirer RenoDX NR supprime uniquement l’extension reconnue avec copie de récupération. ReShade, le modèle NR et les autres extensions sont conservés.",
 "RenoDX Neural Rendering ist von RenoDX HDR und dem früheren AIO getrennt. Das Video verwendet renodx-dlss5-v8.5-model.addon64 aus Discord; hier wird die andere Version 8.5.0-rc10 vom Community-Mirror RankFTW/rhi-repo angeboten. Für die genaue Videodatei Add-on importieren verwenden.\n\n1. Die x64-Datei und DirectX 12 unter Programmdatei und Grafik wählen. Keine DX11/Vulkan-Bridges werden installiert.\n2. Bei OptiScaler zuerst Neural Rendering deaktivieren und die Einstellungen anwenden. Andere Funktionen dürfen bleiben.\n3. ReShade mit Add-ons installieren, danach RenoDX NR installieren / aktualisieren oder Add-on importieren. Das vorhandene NR-Modell bleibt erhalten; andernfalls wird ein Modell für RTX 4000/5000 geladen. Änderungen werden gesichert.\n4. Spiel neu starten, DLSS SR aktivieren und ReShade mit Pos1 oder der gewählten Taste öffnen. Unter DLSS 5 Neural Rendering das Modell prüfen und NR aktivieren. Mit einem Durchlauf beginnen und FPS sowie Bild in derselben Szene vergleichen. Render arbeitet vor dem Upscaling, Upscaled danach; Present kann teuer sein. Optionen hängen von der Version ab.\n\nNeural Rendering kann die FPS reduzieren: Flüssigkeit, HDR und Kompatibilität sind nicht garantiert. FG/MFG und Streamline bleiben getrennt. Anti-Cheat wird nicht deaktiviert. RenoDX NR entfernen löscht nur das erkannte Add-on mit Wiederherstellungskopie. ReShade, NR-Modell und andere Add-ons bleiben erhalten.",
 "RenoDX Neural Rendering é separado do RenoDX HDR e do AIO anterior. O vídeo usa renodx-dlss5-v8.5-model.addon64 do Discord; aqui está disponível a versão diferente 8.5.0-rc10 do espelho comunitário RankFTW/rhi-repo. Use Importar complemento para o ficheiro exato.\n\n1. Escolha o executável x64 e DirectX 12 em Executável e gráficos. Não são instaladas pontes DX11/Vulkan.\n2. Se usa OptiScaler, desative Neural Rendering e aplique antes de instalar. As outras funções podem permanecer.\n3. Clique em Instalar ReShade com complementos e depois Instalar / actualizar RenoDX NR ou Importar complemento. O modelo NR existente é preservado; se faltar, é descarregado para RTX 4000/5000. As alterações têm cópia de segurança.\n4. Reinicie o jogo, ative DLSS SR e abra ReShade com Home ou a tecla configurada. Em DLSS 5 Neural Rendering, confirme o modelo e ative NR. Comece com uma passagem e compare FPS e imagem na mesma cena. Render atua antes do aumento de resolução, Upscaled depois; Present pode ser pesado. As opções dependem da versão.\n\nNeural Rendering pode reduzir os FPS: fluidez, HDR e compatibilidade não são garantidos. FG/MFG e Streamline continuam separados. O anti-cheat não é desativado. Remover RenoDX NR elimina apenas o complemento reconhecido com cópia de recuperação. Preserva ReShade, modelo NR e outros complementos.");return Intro+"\n\n"+ApiHelp+"\n\n"+text.Substring(text.IndexOf("\n\n",StringComparison.Ordinal)+2);}}
 public static string ApiHelp {get{return T("API grafica non confermata come DirectX 12. Apri Eseguibile e grafica, seleziona DirectX 12 e salva per questo gioco. Automatica non conferma l’API; questa scelta non aggiunge supporto DX12 al gioco.","Graphics API not confirmed as DirectX 12. Open Executable and graphics, select DirectX 12 and save for this game. Automatic does not confirm the API; this choice does not add DX12 support.","API gráfica no confirmada como DirectX 12. Abre Ejecutable y gráficos, elige DirectX 12 y guarda. Automática no confirma la API ni añade compatibilidad DX12.","API graphique non confirmée DirectX 12. Ouvrez Exécutable et graphismes, choisissez DirectX 12 et enregistrez. Automatique ne confirme pas l’API ; ce choix n’ajoute pas DX12.","Grafik-API nicht als DirectX 12 bestätigt. Programmdatei und Grafik öffnen, DirectX 12 wählen und speichern. Automatisch bestätigt keine API; die Auswahl ergänzt keine DX12-Unterstützung.","API gráfica não confirmada como DirectX 12. Abra Executável e gráficos, selecione DirectX 12 e guarde. Automática não confirma a API nem adiciona suporte DX12.");}}
 public static string Failure {get{return T("RenoDX NR: configurazione non compatibile. Consulta i requisiti qui sotto.","RenoDX NR: incompatible configuration. See the requirements below.","RenoDX NR: configuración incompatible. Consulta los requisitos.","RenoDX NR : configuration incompatible. Consultez les prérequis.","RenoDX NR: inkompatible Konfiguration. Voraussetzungen beachten.","RenoDX NR: configuração incompatível. Consulte os requisitos.");}}
 static Exception Invalid(){return new Exception(Failure);}
 public static void GuardModelRemoval(Game g){if(RenoDx.AllAddons(g).Any(f=>Regex.IsMatch(Path.GetFileName(f),"dlss5|neural",RegexOptions.IgnoreCase)))throw new Exception(T("Rimuovi prima l’add-on Neural Rendering dalla scheda DLSS 5 · ReShade.","Remove the Neural Rendering add-on in DLSS 5 · ReShade first.","Quita primero el complemento Neural Rendering en DLSS 5 · ReShade.","Retirez d’abord l’extension Neural Rendering dans DLSS 5 · ReShade.","Zuerst das Neural-Rendering-Add-on unter DLSS 5 · ReShade entfernen.","Remova primeiro o complemento Neural Rendering em DLSS 5 · ReShade."));}
 public static void ValidateAddon(string file){if(!Regex.IsMatch(Path.GetFileName(file),@"^renodx-dlss5(?:-v[0-9.]+-model)?\.addon64$",RegexOptions.IgnoreCase)||!DlssCore.Pe64(file)||new FileInfo(file).Length>32000000)throw Invalid();string text=Encoding.ASCII.GetString(File.ReadAllBytes(file));if(!text.Contains("RenoDX")||!text.Contains("Neural Rendering"))throw Invalid();}
 public sealed class Release {public string Tag,Url,Digest;public long Size;public Version Version;public int Revision;}
 public static Release Latest(string json){var parser=new System.Web.Script.Serialization.JavaScriptSerializer{MaxJsonLength=32000000};var list=parser.Deserialize<List<Dictionary<string,object>>>(json);var candidates=new List<Release>();foreach(var row in list){string tag=Convert.ToString(row["tag_name"]);var match=Regex.Match(tag,@"^renodx-dlss5-(\d+\.\d+(?:\.\d+)?)(?:-rc(\d+))?$");if(!match.Success||Convert.ToBoolean(row["draft"]))continue;var assets=((System.Collections.IEnumerable)row["assets"]).Cast<Dictionary<string,object>>().Where(a=>Convert.ToString(a["name"])=="renodx-dlss5_"+tag.Substring("renodx-dlss5-".Length)+".zip").ToArray();if(assets.Length!=1)continue;var a1=assets[0];string url=Convert.ToString(a1["browser_download_url"]),hash=a1.ContainsKey("digest")?Convert.ToString(a1["digest"]):"";long size=Convert.ToInt64(a1["size"]);if(url!="https://github.com/RankFTW/rhi-repo/releases/download/"+tag+"/"+Convert.ToString(a1["name"])||!Regex.IsMatch(hash,@"^sha256:[a-fA-F0-9]{64}$")||size<4096||size>32000000)continue;string v=match.Groups[1].Value;if(v.Count(c=>c=='.')==1)v+=".0";candidates.Add(new Release{Tag=tag,Url=url,Digest=hash.Substring(7),Size=size,Version=new Version(v),Revision=match.Groups[2].Success?Int32.Parse(match.Groups[2].Value):Int32.MaxValue});}var chosen=candidates.OrderByDescending(r=>r.Version).ThenByDescending(r=>r.Revision).FirstOrDefault();if(chosen==null)throw Invalid();return chosen;}
 public static string Fetch(out Release release){using(var web=new DlssCore.DownloadClient()){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;web.Headers[HttpRequestHeader.UserAgent]="HDLSS";web.Headers[HttpRequestHeader.CacheControl]="no-cache";release=Latest(web.DownloadString("https://api.github.com/repos/RankFTW/rhi-repo/releases?per_page=100"));if(release.Version<=new Version(8,5,0)){release=new Release{Tag="v8.5-model",Url=SourcePage,Digest=CurrentHash,Size=3197952,Version=new Version(8,5,0),Revision=Int32.MaxValue};return Bundled();}string dir=Path.Combine(Core.Data,"renodx-nr-packages",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string zip=Path.Combine(dir,"addon.zip");web.DownloadFile(release.Url,zip);if(new FileInfo(zip).Length!=release.Size||!DlssCore.Hash(zip).Equals(release.Digest,StringComparison.OrdinalIgnoreCase))throw Invalid();File.WriteAllText(Path.Combine(dir,"source.json"),Core.Json.Serialize(release));return Extract(zip,dir);}}
 public static string Extract(string zip,string dir){using(var z=new ZipArchive(File.OpenRead(zip),ZipArchiveMode.Read)){if(z.Entries.Count!=1||z.Entries[0].FullName!=Name||z.Entries[0].Length>32000000)throw Invalid();string file=DlssCore.Safe(dir,Name);using(var input=z.Entries[0].Open())using(var output=File.Create(file))input.CopyTo(output);ValidateAddon(file);return file;}}
 public static string[] Detected(Game g){return RenoDx.AllAddons(g).Where(f=>{try{ValidateAddon(f);return true;}catch{return false;}}).ToArray();}
 public static string Early(string ini,bool enabled,string addonName=Name){var values=MfgAddon.Entries(Core.Get(ini,"ADDON","LoadFromDllMain"));bool found=values.Any(x=>x.Equals(addonName,StringComparison.OrdinalIgnoreCase));if(found==enabled)return ini;values.RemoveAll(x=>x.Equals(addonName,StringComparison.OrdinalIgnoreCase));if(enabled)values.Add(addonName);return Core.Set(ini,"ADDON","LoadFromDllMain",String.Join(",",values.Select(x=>x.Replace(",",",,"))));}
 public static DlssScan Check(Game g){Core.Closed(g);var scan=DlssCore.Inspect(g,true,false);if(g.ProtectedInstall||scan.Blockers.Count>0)throw new Exception(Failure+"\n"+String.Join("\n",scan.Blockers));if(InjectionSetup.Profile(g).Api!="dx12")throw new Exception(ApiHelp);if(scan.Proxy!=""&&!String.Equals(Core.Get(scan.Ini,"DlssNr","Enabled"),"false",StringComparison.OrdinalIgnoreCase))throw new Exception(T("Disabilita Neural Rendering nella scheda OptiScaler e premi Applica impostazioni, poi riprova.","Disable Neural Rendering in the OptiScaler tab and click Apply settings, then retry.","Desactiva Neural Rendering en OptiScaler, aplica los ajustes y vuelve a intentarlo.","Désactivez Neural Rendering dans OptiScaler, appliquez et réessayez.","Neural Rendering unter OptiScaler deaktivieren, Einstellungen anwenden und erneut versuchen.","Desative Neural Rendering no OptiScaler, aplique e tente novamente."));return scan;}
 public static DlssPlan Prepare(Game g,string addon,string runtime,string release){var scan=Check(g);ValidateAddon(addon);if(!DlssCore.Pe64(runtime))throw Invalid();var loaders=RenoDx.Loaders(scan.Folder);if(loaders.Count!=1||!Encoding.ASCII.GetString(File.ReadAllBytes(DlssCore.Safe(scan.Folder,loaders[0]))).Contains("LoadFromDllMain"))throw Invalid();if(loaders[0]=="ReShade64.dll"&&(scan.Proxy==""||Core.Get(scan.Ini,"Plugins","LoadReshade")!="true"))throw Invalid();string config=MfgAddon.ConfigName(scan.Folder),cp=DlssCore.Safe(scan.Folder,config),ini=File.Exists(cp)?File.ReadAllText(cp):"",relative=MfgAddon.AddonName(scan.Folder,ini).Replace(MfgAddon.Name,Name);var detected=Detected(g);if(detected.Length==1)relative=detected[0].Substring(scan.Folder.TrimEnd('\\').Length+1);string target=DlssCore.Safe(scan.Folder,relative);if(RenoDx.AllAddons(g).Any(f=>!f.Equals(target,StringComparison.OrdinalIgnoreCase)&&Regex.IsMatch(Path.GetFileName(f),"dlss|neural",RegexOptions.IgnoreCase)))throw Invalid();if(MfgAddon.Entries(Core.Get(ini,"ADDON","DisabledAddons")).Any(x=>Regex.IsMatch(x,"DLSS|Neural",RegexOptions.IgnoreCase)))throw Invalid();string marker=DlssCore.Safe(scan.Folder,Marker);var m=File.Exists(marker)?DlssCore.ReadManifest(scan.Folder,Marker):new DlssManifest{Game=g.Id,Folder=scan.Folder,BackupRoot="renodx-nr-backups/"+Guid.NewGuid().ToString("N"),PreviousOwner="Before RenoDX NR"};if(m.Files.Any(f=>f.Name.EndsWith(".addon64",StringComparison.OrdinalIgnoreCase)&&f.Name!=relative))throw Invalid();m.Build="RenoDX NR";m.Release=release;var p=new DlssPlan{Folder=scan.Folder,MarkerName=Marker,MarkerExpected=File.Exists(marker)?DlssCore.Hash(marker):null,Manifest=m,Summary=Title+" · "+release+"\n"+g.Name+"\nSHA256 "+DlssCore.Hash(addon)};Add(p,relative,addon,null);if(!File.Exists(scan.Runtime)||DlssCore.Hash(runtime)!=DlssCore.Hash(scan.Runtime))Add(p,"nvngx_dlssnr.dll",runtime,null);string updated=Early(ini,true,Path.GetFileName(relative));if(updated!=ini)Add(p,config,null,Encoding.UTF8.GetBytes(updated));return p;}
 static void Add(DlssPlan p,string name,string source,byte[] bytes){string file=DlssCore.Safe(p.Folder,name);p.Changes.Add(new DlssChange{Name=name,Source=source,SourceHash=source==null?null:DlssCore.Hash(source),Bytes=bytes,Expected=File.Exists(file)?DlssCore.Hash(file):null});}
 public static DlssPlan Restore(Game g){Core.Closed(g);string root=Path.GetDirectoryName(g.Exe);var m=DlssCore.ReadManifest(root,Marker);var p=new DlssPlan{Folder=root,MarkerName=Marker,Uninstall=true,Summary=Title};foreach(var f in m.Files){string dst=DlssCore.Safe(root,f.Name),backup=f.Before==null?null:DlssCore.Safe(Core.Data,f.Backup),hash=File.Exists(dst)?DlssCore.Hash(dst):null;if(backup!=null&&(!File.Exists(backup)||DlssCore.Hash(backup)!=f.Before))throw Invalid();if(f.Name.EndsWith(".ini",StringComparison.OrdinalIgnoreCase)){if(hash==null)continue;string current=File.ReadAllText(dst),prior=backup==null?"":File.ReadAllText(backup);string addonName=Path.GetFileName(m.Files.First(f1=>f1.Name.EndsWith(".addon64",StringComparison.OrdinalIgnoreCase)).Name);if(Early(prior,true,addonName)==prior)continue;string updated=Early(current,false,addonName);if(current!=updated)Add(p,f.Name,null,Encoding.UTF8.GetBytes(updated));}else{if(hash!=f.After)throw Invalid();p.Changes.Add(new DlssChange{Name=f.Name,Expected=hash,Source=backup,SourceHash=f.Before,Delete=backup==null,RestoreAttributes=f.Attributes});}}p.Changes.Add(new DlssChange{Name=Marker,Expected=DlssCore.Hash(DlssCore.Safe(root,Marker)),Delete=true});return p;}
 public static DlssPlan Remove(Game g){Core.Closed(g);if(g.ProtectedInstall)throw new Exception(g.Evidence);var files=Detected(g);if(files.Length!=1)throw Invalid();string root=Path.GetDirectoryName(g.Exe),relative=files[0].Substring(root.TrimEnd('\\').Length+1);var plan=new DlssPlan{Folder=root,Uninstall=true,Summary=Title};plan.Changes.Add(new DlssChange{Name=relative,Expected=DlssCore.Hash(files[0]),Delete=true});string config=MfgAddon.ConfigName(root),path=DlssCore.Safe(root,config);if(File.Exists(path)){string ini=File.ReadAllText(path),updated=Early(ini,false,Path.GetFileName(files[0]));if(updated!=ini)Add(plan,config,null,Encoding.UTF8.GetBytes(updated));}string marker=DlssCore.Safe(root,Marker);if(File.Exists(marker))plan.Changes.Add(new DlssChange{Name=Marker,Expected=DlssCore.Hash(marker),Delete=true});return plan;}
 public static bool Busy;
 public static FrameworkElement Panel(Window owner,Game game,Action changed,bool includePrerequisite=true){var body=new StackPanel{Margin=new Thickness(0,8,0,8)};body.Children.Add(Dialogs.Text(Title+" · RenoDX",20));body.Children.Add(Dialogs.Text(Intro,14));Button removeButton=null;var installButtons=new List<Button>();var state=Dialogs.Text("",14);body.Children.Add(state);Action refresh=()=>{if(removeButton!=null)removeButton.IsEnabled=Detected(game).Length==1;try{var m=DlssCore.ReadManifest(Path.GetDirectoryName(game.Exe),Marker);bool valid=m.Files.Where(f=>f.Name.EndsWith(".addon64")).Any(f=>File.Exists(DlssCore.Safe(m.Folder,f.Name))&&DlssCore.Hash(DlssCore.Safe(m.Folder,f.Name))==f.After);state.Text=valid?m.Release+" · "+Appearance.Localize("Installed files; verify activation in game."):Appearance.Localize("External installation; version not verified.");}catch{state.Text=Appearance.Localize("Not installed");}var found=Detected(game);if(found.Length==1)state.Text=Path.GetFileName(found[0])+" · "+Appearance.Localize("Installed files; verify activation in game.");for(int i=0;i<installButtons.Count;i++){bool present=i==0?RenoDx.Loaders(Path.GetDirectoryName(game.Exe)).Any(n=>Encoding.ASCII.GetString(File.ReadAllBytes(Path.Combine(Path.GetDirectoryName(game.Exe),n))).Contains("LoadFromDllMain")):found.Length==1;installButtons[i].Style=owner.TryFindResource(present?"Installed":"Primary") as Style;}};refresh();var actions=new StackPanel{HorizontalAlignment=HorizontalAlignment.Left};body.Children.Add(actions);var status=Dialogs.Text("",14);var emptyStyle=new Style(typeof(TextBlock),status.Style);emptyStyle.Triggers.Add(new Trigger{Property=TextBlock.TextProperty,Value="",Setters={new Setter(UIElement.VisibilityProperty,Visibility.Collapsed)}});status.Style=emptyStyle;body.Children.Add(status);
 Action<string,Func<Task>,string> button=(text,action,style)=>{var b=new Button{Content=text,Margin=new Thickness(0,0,8,8),Padding=new Thickness(12,10,12,10),Style=owner.TryFindResource(style) as Style};actions.Children.Add(b);if(style=="Primary")installButtons.Add(b);if(style=="RestoreAction")removeButton=b;b.Click+=async(s,e)=>{if(Busy||InlineOperation.IsBusy||ModCenter.Busy||RenoDxUi.IsBusy)return;Busy=true;actions.IsEnabled=false;try{await action();refresh();changed();}catch(Exception ex){status.Text=Appearance.Localize(ex.Message);ActivityLog.Write(ex.Message);}finally{Busy=false;actions.IsEnabled=true;}};};
 button(T("Eseguibile e grafica…","Executable and graphics…","Ejecutable y gráficos…","Exécutable et graphismes…","Programmdatei und Grafik…","Executável e gráficos…"),()=>{InjectionSetup.Show(owner,game,refresh);return Task.FromResult(0);},"InfoAction");
 Action<string> progress=msg=>owner.Dispatcher.Invoke(new Action(()=>status.Text=Appearance.Localize(msg)));
 button(T("1. Installa ReShade con add-on","1. Install ReShade with add-ons","1. Instalar ReShade con complementos","1. Installer ReShade avec extensions","1. ReShade mit Add-ons installieren","1. Instalar ReShade com complementos"),async()=>{Check(game);string origin="";string file=await Task.Run(()=>RenoDx.Fetch(false,progress,out origin));await InlineOperation.Apply(game,RenoDx.InstallReShade(game,file,origin),status,refresh);},"Primary");
 Func<string,Task> install=async local=>{var scan=Check(game);var hardware=DlssHardware.Detect();hardware.Validate(hardware.Series,scan.Runtime);Release release=null;string addon=local??await Task.Run(()=>Fetch(out release));string origin="";string runtime=await Task.Run(()=>NrModels.EnsureRuntime(true,scan.Runtime,hardware.Series,progress,out origin));await InlineOperation.Apply(game,Prepare(game,addon,runtime,local==null?release.Tag+" · "+(release.Url==SourcePage?"RenoDX Discord":"RankFTW/rhi-repo"):Path.GetFileName(local)),status,refresh);};
 button(T("2. Installa / aggiorna RenoDX NR","2. Install / update RenoDX NR","2. Instalar / actualizar RenoDX NR","2. Installer / mettre à jour RenoDX NR","2. RenoDX NR installieren / aktualisieren","2. Instalar / atualizar RenoDX NR"),()=>install(null),"Primary");
 button(T("Importa un’altra build…","Import another build…","Importar otra versión…","Importer une autre version…","Anderen Build importieren…","Importar outra versão…"),async()=>{var d=new Microsoft.Win32.OpenFileDialog{Filter="RenoDX NR|renodx-dlss5*.addon64"};if(d.ShowDialog(owner)==true)await install(d.FileName);},"InfoAction");
 button(T("Rimuovi RenoDX NR","Remove RenoDX NR","Quitar RenoDX NR","Retirer RenoDX NR","RenoDX NR entfernen","Remover RenoDX NR"),async()=>{await InlineOperation.Apply(game,Remove(game),status,refresh);},"RestoreAction");
 var source=new Button{Content=T("Apri download RenoDX","Open RenoDX downloads","Abrir descargas RenoDX","Ouvrir les téléchargements RenoDX","RenoDX-Downloads öffnen","Abrir downloads RenoDX"),Margin=new Thickness(0,0,8,8)};source.Click+=(s,e)=>System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(SourcePage){UseShellExecute=true});actions.Children.Add(source);body.Children.Add(Dialogs.Text(Policy,14));body.Children.Add(NavigationSession.Track("renodx-nr-help",new Expander{Header=T("Istruzioni e requisiti · leggi prima di installare","Instructions and requirements · read before installing","Instrucciones y requisitos · leer antes de instalar","Instructions et prérequis · lire avant l’installation","Anleitung und Voraussetzungen · vor Installation lesen","Instruções e requisitos · leia antes de instalar"),Content=Dialogs.Text(Help,14),Margin=new Thickness(0,14,0,8)}));if(!includePrerequisite){installButtons[0].Visibility=Visibility.Collapsed;installButtons[1].Content=Convert.ToString(installButtons[1].Content).Substring(3);body.Children.RemoveAt(0);}bool subscribed=false;Action onChanged=()=>body.Dispatcher.BeginInvoke(new Action(refresh));body.Loaded+=(s,e)=>{if(!subscribed){ModUpdates.Changed+=onChanged;subscribed=true;}refresh();};body.Unloaded+=(s,e)=>{if(subscribed){ModUpdates.Changed-=onChanged;subscribed=false;}};refresh();return body;}
